mapper.select:
SELECT MIN(settlement_id) AS settlement_id, merchant_id, merchant_name, business_number, settlement_month, MAX(status_changed_at) AS status_changed_at, SUM(settlement_amount) AS settlement_amount, MIN(status) AS status, MAX(created_at) AS created_at, MAX(updated_at) AS updated_at, (SELECT COUNT(*) FROM payment p WHERE p.merchant_id = s.merchant_id AND DATE_FORMAT(p.transmission_date, '%Y-%m') = s.settlement_month AND p.status = 'SUCCESS') AS success_count, (SELECT COUNT(*) FROM payment p WHERE p.merchant_id = s.merchant_id AND DATE_FORMAT(p.transmission_date, '%Y-%m') = s.settlement_month AND p.status = 'CANCELED') AS cancel_count FROM settlement s
AND settlement_month >= #{startMonth}
AND settlement_month <= #{endMonth}
AND status = #{status}
AND merchant_name LIKE CONCAT('%', #{merchantName}, '%')
AND business_number = #{businessNumber}
AND merchant_id = #{merchantId}
GROUP BY merchant_id, merchant_name, business_number, settlement_month ORDER BY settlement_month DESC LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM (
SELECT merchant_id, settlement_month
FROM settlement


        AND settlement_month >= #{startMonth}


        AND settlement_month <= #{endMonth}


        AND status = #{status}


        AND merchant_name LIKE CONCAT('%', #{merchantName}, '%')


        AND business_number = #{businessNumber}


        AND merchant_id = #{merchantId}


GROUP BY merchant_id, settlement_month
) AS sub

mapper.update:
UPDATE settlement
SET status = #{status}, status_changed_at = NOW()
WHERE merchant_id = #{merchantId}
  AND settlement_month = #{settlementMonth}

